INSERT OR IGNORE INTO articles(id,title,slug,excerpt,content,image_url,image_alt,author_name,status,published_at,seo_title,seo_description) VALUES
('art-01','A neighborhood library makes room for new ideas','community-library-project','A small community space is finding new ways to bring readers together.','<p>This illustrative feature explores how a neighborhood library can become a welcoming place for readers, learners, and local groups.</p><h2>A place to meet</h2><p>Residents helped shape a flexible space for workshops, reading groups, and quiet study. The example is fictional and provided for development use.</p><p>Its organizers say the most useful changes began with listening to the people who use the library every day.</p>','/images/placeholder.svg','Illustrative books and reading space','Maya Chen','published','2026-09-18','A neighborhood library makes room for new ideas','An illustrative story about a community library and the role it can play.'),
('art-02','Small businesses rethink the high street','small-business-high-street','Independent shops are experimenting with shared events and more welcoming storefronts.','<p>This sample article looks at practical ways fictional local businesses are making town centers more inviting.</p><h2>Working together</h2><p>From shared late openings to seasonal markets, collaboration can help small shops reach new neighbors.</p>','/images/placeholder.svg','Illustrative storefront','Sam Rivera','published','2026-09-16','',''),
('art-03','What a repair café can teach us about design','repair-cafe-design','Volunteer fixers are helping neighbors see everyday objects in a new light.','<p>This fictional report follows a repair café where volunteers share skills and help extend the useful life of household items.</p><h2>Learning by doing</h2><p>Visitors leave with more than a repaired object: they gain confidence to try simple fixes themselves.</p>','/images/placeholder.svg','Illustrative tools on a workbench','Ari Patel','published','2026-09-14','',''),
('art-04','A thoughtful guide to a calmer morning','calmer-morning-guide','A few small routines can make the start of the day feel less rushed.','<p>This practical, illustrative guide offers gentle ideas for creating a morning routine that fits real life.</p><h2>Start small</h2><p>Choose one helpful step, such as setting out breakfast or stepping outside for a few minutes.</p>','/images/placeholder.svg','Illustrative morning coffee','Nora James','published','2026-09-12','',''),
('art-05','Local artists bring color to a shared garden','artists-shared-garden','A community garden project invited artists and neighbors to make something together.','<p>This entirely illustrative story considers how art can help a shared garden feel like a community space.</p><h2>Making it together</h2><p>Participants designed signs, painted planters, and created a small outdoor gallery.</p>','/images/placeholder.svg','Illustrative community garden','Maya Chen','published','2026-09-10','',''),
('art-06','How open data can help people understand a city','open-data-city-guide','Clear public information can help residents ask better questions about their neighborhoods.','<p>This sample explainer introduces open data through fictional examples and plain-language ideas.</p><h2>Make information useful</h2><p>Good public data is documented, accessible, and presented with enough context to avoid misleading conclusions.</p>','/images/placeholder.svg','Illustrative city map','Sam Rivera','published','2026-09-08','',''),
('art-07','A community kitchen shares more than recipes','community-kitchen-recipes','A shared table can bring neighbors together around food, learning, and conversation.','<p>This illustrative feature looks at a fictional community kitchen and its weekly recipe exchange.</p><h2>Food and connection</h2><p>Participants trade affordable recipes and stories about the dishes they grew up with.</p>','/images/placeholder.svg','Illustrative shared meal','Ari Patel','published','2026-09-06','',''),
('art-08','The new life of a historic railway path','historic-railway-path','An old route has become a place for walking, cycling, and noticing local history.','<p>This fictional travel feature follows a disused railway path reimagined as a public greenway.</p><h2>Take the slower route</h2><p>Interpretive signs connect the landscape to its industrial past while the path supports everyday recreation.</p>','/images/placeholder.svg','Illustrative leafy walking path','Nora James','published','2026-09-04','',''),
('art-09','A beginner-friendly guide to digital privacy','digital-privacy-beginners','Simple account habits can make online life easier to manage.','<p>This sample guide explains a few common privacy practices in straightforward language.</p><h2>Review the basics</h2><p>Use unique passwords, turn on multi-factor authentication where available, and review app permissions from time to time.</p>','/images/placeholder.svg','Illustrative laptop and notebook','Maya Chen','published','2026-09-02','',''),
('art-10','Why public parks matter in every season','public-parks-every-season','Parks support rest, play, and connection throughout the year.','<p>This illustrative essay explores how people use parks in every season, from summer picnics to winter walks.</p><h2>Spaces for everyone</h2><p>Thoughtful maintenance and accessible paths help more people enjoy local green space.</p>','/images/placeholder.svg','Illustrative green public park','Sam Rivera','published','2026-08-30','',''),
('art-11','The science of a good night’s rest','science-of-rest','Researchers continue to study the many factors that shape sleep.','<p>This sample explainer is for demonstration only and does not replace professional health advice.</p><h2>Everyday habits</h2><p>Regular routines and a comfortable sleep environment may support rest for many people.</p>','/images/placeholder.svg','Illustrative bedroom at dusk','Ari Patel','published','2026-08-28','',''),
('art-12','A studio visit with a maker of everyday objects','studio-visit-maker','A fictional maker shares how useful objects take shape from early sketches.','<p>This illustrative studio visit follows a maker from a rough drawing through simple prototypes and a finished object.</p><h2>Materials matter</h2><p>Choosing durable, repairable materials is part of the creative process.</p>','/images/placeholder.svg','Illustrative design studio','Nora James','published','2026-08-26','','');

