('page-about','About Us','about','<p>We are an independent editorial project sharing thoughtful stories about people, ideas, and everyday life.</p><p>This development website uses sample content to demonstrate the publishing system.</p>','published','About Us | Fieldnote','Learn about Fieldnote, an illustrative editorial publication.'),
('page-contact','Contact Us','contact','<p>For this demo, please use the site administrator account to update contact information before launch.</p>','published','Contact Us | Fieldnote','Contact information for Fieldnote.'),
('page-privacy','Privacy Policy','privacy-policy','<p>This sample privacy page is placeholder content. Replace it with a policy reviewed for your organization and jurisdiction before publication.</p>','published','',''),
('page-terms','Terms and Conditions','terms','<p>This sample terms page is placeholder content. Have it reviewed before using this site publicly.</p>','published','',''),
('page-editorial','Editorial Policy','editorial-policy','<p>Our illustrative editorial policy values accuracy, clarity, fairness, and corrections when needed.</p>','published','','');
